const cnapsValue=(data,...keys)=>{for(const key of keys)if(data?.[key]!==undefined&&data[key]!==null)return data[key];return ''};
const cnapsTone=value=>{const s=String(value||'').trim().toUpperCase();if(['ACCEPTÉ','ACCEPTE','CARTE PROFESSIONNELLE OK','ACTIF'].includes(s))return'green';if(['TRANSMIS','ENREGISTRÉ','ENREGISTRE','EN INSTRUCTION'].includes(s))return'blue';if(['REFUSÉ','REFUSE','INACTIF'].includes(s))return'red';return'amber'};
const cnapsDate=value=>{if(!value)return'—';const date=new Date(value);return Number.isNaN(date.getTime())?'—':new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium'}).format(date)};
function renderReglementaire(c,data){const box=document.querySelector('#cnapsPanel');if(!box)return;if(data.linked===false){box.innerHTML=`<div class="cnaps-head"><div><h4>Suivi CNAPS — Gestion stagiaires</h4><small>Données en lecture seule</small></div><button type="button" class="btn" id="cnapsRefresh">Actualiser</button></div><div class="cnaps-empty">${esc(data.message)}</div>`;cnapsRefresh.onclick=()=>loadReglementaire(c);return}const cnaps=data.cnaps||data,status=cnapsValue(cnaps,'cnaps_status','statut_cnaps','status','statut')||'INCONNU',titles=cnapsValue(cnaps,'titles','titres','professional_titles')||[],checked=cnapsValue(cnaps,'last_checked_at','last_verification_at','date_derniere_verification','checked_at'),url=cnapsValue(data,'trainee_url','stagiaire_url','fiche_url','url');box.innerHTML=`<div class="cnaps-head"><div><h4>Suivi CNAPS — Gestion stagiaires</h4><small>Données en lecture seule</small></div><div class="cnaps-actions"><button type="button" class="btn" id="cnapsRefresh">Actualiser</button>${url?`<a class="btn blue" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Ouvrir la fiche stagiaire</a>`:''}</div></div><div class="cnaps-summary"><span>Statut CNAPS</span><b class="cnaps-badge ${cnapsTone(status)}">${esc(status)}</b></div>${titles.length?`<div class="cnaps-titles">${titles.map(title=>{const name=cnapsValue(title,'type','title','titre','name')||'Titre CNAPS',state=cnapsValue(title,'state','status','etat')||'INCONNU',expiry=cnapsValue(title,'expires_at','expiration_date','date_expiration');return`<article><div><strong>${esc(name)}</strong><b class="cnaps-badge ${cnapsTone(state)}">${esc(state)}</b></div><p>Expiration : ${cnapsDate(expiry)}</p>${title.expires_before_training===true?'<p class="cnaps-warning">Expiration avant la formation</p>':''}</article>`}).join('')}</div>`:'<div class="cnaps-empty cnaps-muted">Aucun titre CNAPS retourné.</div>'}<p class="cnaps-checked">Dernière vérification : ${checked?fmt(checked):'Non disponible'}</p>${cnaps.nub_missing===true||cnaps.nub_present===false?'<p class="cnaps-notice">NUB absent : la vérification CNAPS est impossible.</p>':''}${cnaps.cnaps_unavailable===true?'<p class="cnaps-notice">Annuaire CNAPS indisponible lors de la dernière vérification.</p>':''}`;cnapsRefresh.onclick=()=>loadReglementaire(c)}
