  const amountHT=wedofGet(p,'trainingActionInfo.totalExcl','amountHt','amountHT','amounts.excludingTax'),amountTTC=wedofGet(p,'trainingActionInfo.totalIncl','amountTtc','amountTTC','amounts.includingTax'),toInvoice=wedofGet(p,'amountToInvoice','amounts.remainingToInvoice','remainingToBill');
  const method=resource.match_method==='email'?'E-mail':resource.match_method==='phone'?'Téléphone':wedofLabel(resource.match_method||'Non précisée');
  const rows=items=>items.filter(([,v])=>wedofPresent(v)).map(([l,v])=>`<div class="wedof-fact"><small>${l}</small><strong>${esc(wedofValue(v))}</strong></div>`).join('');
  const details=(title,value)=>wedofPresent(value)?`<details class="wedof-sub wedof-collapse"><summary>${title}</summary><p>${esc(wedofValue(value))}</p></details>`:'';
  const money=[['HT',amountHT],['TTC',amountTTC],['Coût pédagogique',training.teachingFees],['Frais supplémentaires',training.additionalFees],['Montant à facturer',toInvoice]].filter(([,v])=>wedofPresent(v));
  const historyRows=(Array.isArray(history)?history.flatMap((x,i)=>Object.entries(x).map(([name,date])=>({name:name==='date'?(x.state||x.status||x.type||`Événement ${i+1}`):name,date}))):Object.entries(history).map(([name,date])=>({name,date}))).filter(x=>wedofPresent(x.date)&&!Number.isNaN(new Date(x.date).getTime())).sort((a,b)=>new Date(a.date)-new Date(b.date));
